# Lightweight file logging for recoverable UI/import/export/config failures.
_LOG_DIR = Path.home() / ".ecograph"
try:
    _LOG_DIR.mkdir(parents=True, exist_ok=True)
    logging.basicConfig(
        filename=str(_LOG_DIR / "ecograph.log"),
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
    )
except OSError:
    # Logging must never prevent the desktop app or its self-test from starting.
    logging.basicConfig(level=logging.WARNING)
