def _ref_color():
    """Theme-aware color for reference/equality/zero lines."""
    theme = str(globals().get("ACTIVE_GRAPH_THEME", "Neon Dark"))
    return "#111111" if theme == "Academic Paper" else ("#253247" if theme == "Light Theme" else "#FFFFFF")

def _info_box_facecolor(kind="normal"):
    """Readable annotation background for the active graph theme.

    kind='warning' keeps a warning tint while switching to pale colors on light themes.
    """
    if ACTIVE_GRAPH_THEME == "Academic Paper":
        return "#FFF4F4" if kind == "warning" else ("#F0FDF4" if kind == "success" else "#FFFFFF")
    if ACTIVE_GRAPH_THEME == "Light Theme":
        return "#FFF1F2" if kind == "warning" else ("#ECFDF3" if kind == "success" else "#F5F8FC")
    return "#2A1016" if kind == "warning" else ("#102A25" if kind == "success" else "#0B1220")

