TOPIC_SCHEMA = {}
def _spec(key):
    return COMMON[key] if key in COMMON else PARAMS[key]
def schema(topic, *keys):
    try:
        specs = [_spec(k) for k in keys]
    except KeyError as exc:
        missing = str(exc.args[0]) if exc.args else "<unknown>"
        raise RuntimeError(f"Schema setup failed for topic {topic!r}: missing parameter specification {missing!r}.") from exc
    TOPIC_SCHEMA[topic] = specs
    TOPIC_SCHEMA[topic + "::keys"] = list(keys)

def _override_spec(topic, key, **kw):
    """Change default/min/max of one topic-specific parameter without touching shared PARAMS."""
    idx = TOPIC_SCHEMA[topic + "::keys"].index(key)
    label, default, lo, hi, step = TOPIC_SCHEMA[topic][idx]
    TOPIC_SCHEMA[topic][idx] = (kw.get("label", label), kw.get("default", default), kw.get("lo", lo), kw.get("hi", hi), kw.get("step", step))

