def _offsets_array(offsets):
    """Return scatter offsets as float data, preserving masks as NaN.

    Matplotlib legend proxy artists often use scatter([nan], [nan]); masked
    entries must not be coerced to ordinary zeroes by np.asarray().
    """
    if offsets is None:
        return np.empty((0, 2), dtype=float)
    try:
        masked = np.ma.asarray(offsets, dtype=float)
        data = np.asarray(np.ma.filled(masked, np.nan), dtype=float)
        if data.size == 0:
            return np.empty((0, 2), dtype=float)
        if data.ndim == 1:
            data = data.reshape(1, -1)
        return data
    except (TypeError, ValueError):
        return np.empty((0, 2), dtype=float)


def _maybe_log_scale_from_logs(ax, log_values: np.ndarray, threshold: float = math.log(100.0)) -> bool:
    """Apply log y-scale from precomputed natural-log values only.

    IMPORTANT: never pass raw y-values to this helper. Callers must first filter
    or safely transform positive levels, e.g. ``np.log(np.maximum(y, 1e-12))``.
    The explicit name makes the contract visible at every call site.

    Contract: callers must pass natural-log-transformed positive y-values
    (e.g. np.log(y)); this function cannot reliably infer whether arbitrary
    finite values are raw levels or logs, so it deliberately does not use a
    magnitude heuristic. The log scale is applied when either the range of
    finite log-values exceeds ``threshold`` (default ln(100), i.e. a 100×
    multiplicative span in the underlying positive data), or the maximum
    finite log-value exceeds ln(1e6) (meaning at least one raw level exceeds
    1e6). Non-finite values are ignored and exponent clipping is handled by callers.
    """
    values = np.asarray(log_values, dtype=float)
    finite = values[np.isfinite(values)]
    if finite.size == 0:
        return False
    if (float(np.max(finite) - np.min(finite)) > float(threshold) or
            float(np.max(finite)) > math.log(1e6)):
        ax.set_yscale("log")
        return True
    return False



def _monopoly_optimum(a, b, mc0, mc1, fixed):
    """Shared monopoly-family solution used by both numeric panel and graph.

    Quantities are constrained to [0, a] (non-negative demand domain).
    Shutdown is decided by comparing operating profit with the Q=0 payoff,
    so negative mc0 is supported without changing the cost/profit identities.
    """
    a = max(0.0, float(a))
    b = max(1e-12, float(b))
    mc0 = float(mc0)
    mc1 = max(1e-12, float(mc1))
    fixed = max(0.0, float(fixed))
    q_raw = (a - b * mc0) / (2.0 + b * mc1)
    q_candidate = max(0.0, min(q_raw, a))
    p_candidate = max(0.0, (a - q_candidate) / b)
    candidate_profit = (p_candidate * q_candidate - fixed - mc0 * q_candidate
                        - 0.5 * mc1 * q_candidate * q_candidate)
    shutdown_profit = -fixed
    choke_price = a / b
    shutdown = ((q_candidate <= 1e-12 and choke_price <= mc0 + 1e-12) or
                (q_candidate > 1e-12 and candidate_profit < shutdown_profit - 1e-12))
    q = 0.0 if shutdown else q_candidate
    # No transaction price exists at Q=0; retain demand choke price separately.
    price = p_candidate if q > 0 else 0.0
    mr = (a - 2.0 * q) / b
    mc = mc0 + mc1 * q
    tr = price * q
    tc = fixed + mc0 * q + 0.5 * mc1 * q * q
    profit = tr - tc
    avc = mc0 + 0.5 * mc1 * q if q > 0 else mc0
    atc = tc / q if q > 0 else float('inf')
    return {
        'q_raw': q_raw, 'q_candidate': q_candidate, 'p_candidate': p_candidate,
        'candidate_profit': candidate_profit, 'shutdown_profit': shutdown_profit,
        'choke_price': choke_price, 'shutdown': shutdown, 'q': q, 'price': price,
        'mr': mr, 'mc': mc, 'tr': tr, 'tc': tc, 'profit': profit,
        'avc': avc, 'atc': atc,
    }

def _draw_neon_glow(ax, x, y, color, lw=2.5, label=None, linestyle="-", glow=True):
    if not glow or ACTIVE_GRAPH_THEME in ("Academic Paper", "Light Theme"):
        ax.plot(x, y, color=color, linewidth=max(1.6, lw), label=label, linestyle=linestyle, zorder=5)
        return
    for width, alpha in ((lw * 9, .045), (lw * 6.5, .075), (lw * 4.5, .12), (lw * 2.8, .22)):
        ax.plot(x, y, color=color, linewidth=width, alpha=alpha, linestyle=linestyle, zorder=3)
    ax.plot(x, y, color=color, linewidth=lw, label=label, linestyle=linestyle, zorder=5)
    ax.plot(x, y, color="#FFFFFF", linewidth=max(.65, lw * .22), alpha=.92, linestyle=linestyle, zorder=6)

def _style(ax, fig, draw_grid=True, big_title=True):
    # Consistent typography with selectable dark, light, and print-oriented palettes.
    if ACTIVE_GRAPH_THEME == "Academic Paper":
        fig.patch.set_facecolor("white"); ax.set_facecolor("white")
        tick, label, title, spine, grid = "#222222", "#111111", "#111111", "#444444", "#BBBBBB"
        grid_alpha = .45
    elif ACTIVE_GRAPH_THEME == "Light Theme":
        fig.patch.set_facecolor("#F7F9FC"); ax.set_facecolor("#FFFFFF")
        tick, label, title, spine, grid = "#344054", "#253247", "#172033", "#C7D0DD", "#CBD5E1"
        grid_alpha = .55
    else:
        fig.patch.set_facecolor("#020205"); ax.set_facecolor("#050509")
        tick, label, title, spine, grid = "#D8E7F2", "#E8F4FF", "#FFFFFF", "#344054", "#506070"
        grid_alpha = .28
    ax.tick_params(axis="both", colors=tick, labelsize=9.5, which="both", length=4, width=.8)
    ax.xaxis.label.set_color(label); ax.yaxis.label.set_color(label)
    ax.xaxis.label.set_fontsize(10.5); ax.yaxis.label.set_fontsize(10.5)
    ax.title.set_color(title)
    if big_title:
        ax.title.set_fontsize(13); ax.title.set_fontweight("bold")
    for spine_obj in ax.spines.values(): spine_obj.set_color(spine)
    # Matplotlib warns that supplying line properties with visible=False can
    # re-enable the grid. Only pass styling properties when the grid is enabled.
    if draw_grid:
        ax.grid(True, color=grid, alpha=grid_alpha, linewidth=.7)
    else:
        ax.grid(False)


def _trapz(y, x):
    return float((getattr(np, "trapezoid", None) or np.trapz)(y, x))

def _norm_cdf(z):
    """Standard-normal CDF with stable tails (erfc avoids 1 + erf cancellation)."""
    z = float(z)
    if math.isnan(z):
        return float("nan")
    if z == math.inf:
        return 1.0
    if z == -math.inf:
        return 0.0
    return 0.5 * math.erfc(-z / math.sqrt(2.0))

def _betacf(a, b, x):
    """Continued fraction for the regularized incomplete beta function."""
    MAXIT, EPS, FPMIN = 200, 3e-14, 1e-300
    qab, qap, qam = a + b, a + 1.0, a - 1.0
    c = 1.0
    d = 1.0 - qab * x / qap
    if abs(d) < FPMIN:
        d = FPMIN
    d = 1.0 / d
    h = d
    for m in range(1, MAXIT + 1):
        m2 = 2 * m
        aa = m * (b - m) * x / ((qam + m2) * (a + m2))
        d = 1.0 + aa * d
        if abs(d) < FPMIN:
            d = FPMIN
        c = 1.0 + aa / c
        if abs(c) < FPMIN:
            c = FPMIN
        d = 1.0 / d
        h *= d * c
        aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2))
        d = 1.0 + aa * d
        if abs(d) < FPMIN:
            d = FPMIN
        c = 1.0 + aa / c
        if abs(c) < FPMIN:
            c = FPMIN
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < EPS:
            break
    return h

def _reg_beta(a, b, x):
    if x <= 0.0: return 0.0
    if x >= 1.0: return 1.0
    log_bt = math.lgamma(a+b)-math.lgamma(a)-math.lgamma(b) + a*math.log(x) + b*math.log1p(-x)
    bt = math.exp(log_bt)
    if x < (a + 1.0)/(a + b + 2.0):
        return bt * _betacf(a,b,x) / a
    return 1.0 - bt * _betacf(b,a,1.0-x) / b

def _student_t_cdf(t, df):
    """Student-t CDF with stable central and tail formulas."""
    t = float(t)
    df = float(df)
    if not math.isfinite(df) or df <= 0:
        raise ValueError("Student-t degrees of freedom must be finite and positive.")
    if math.isnan(t):
        raise ValueError("Student-t statistic must not be NaN.")
    if t == math.inf:
        return 1.0
    if t == -math.inf:
        return 0.0
    if t == 0.0:
        return 0.5

    if df >= 1e10:
        # Normal-limit expansion with first finite-df correction. This avoids
        # catastrophic lgamma cancellation in the incomplete-beta expression.
        t_abs = abs(t)
        normal_cdf = 0.5 * math.erfc(-t / math.sqrt(2.0))
        if t_abs > 38.5:
            return float(normal_cdf)
        phi = math.exp(-0.5 * t_abs * t_abs) / math.sqrt(2.0 * math.pi)
        correction = phi * (t_abs * t_abs * t_abs + t_abs) / (4.0 * df)
        return float(min(1.0, max(0.0, normal_cdf - math.copysign(correction, t))))

    root_df = math.sqrt(df)
    t_abs = abs(t)
    if t_abs <= root_df:
        ratio = t_abs / root_df
        y = (ratio * ratio) / (1.0 + ratio * ratio)
        x = 1.0 / (1.0 + ratio * ratio)
    else:
        inv_ratio = root_df / t_abs
        inv2 = inv_ratio * inv_ratio
        x = inv2 / (1.0 + inv2)
        y = 1.0 / (1.0 + inv2)

    a, b = df / 2.0, 0.5
    # If x is in the lower region of I_x(a,b), evaluate the survival tail
    # directly. Otherwise use the equivalent central form to avoid cancellation.
    if x < (a + 1.0) / (a + b + 2.0):
        half_tail = 0.5 * _reg_beta(a, b, x)
        return 1.0 - half_tail if t > 0 else half_tail
    half_delta = 0.5 * _reg_beta(b, a, y)
    return 0.5 + half_delta if t > 0 else 0.5 - half_delta

def _student_t_pvalue(t_stat, df):
    """Two-sided Student-t p-value with a log-domain extreme-tail fallback."""
    t_stat = float(t_stat)
    df = float(df)
    if not math.isfinite(df) or df <= 0:
        raise ValueError("df must be a finite positive number")
    if math.isnan(t_stat):
        raise ValueError("t statistic must not be NaN")
    if math.isinf(t_stat):
        return 0.0
    t_abs = abs(t_stat)
    if t_abs == 0.0:
        return 1.0

    # For enormous df, log-gamma differences in the incomplete-beta formula
    # lose precision (and can overflow for finite df near 1e308). The Student-t
    # tail converges to the normal tail; include the first O(1/df) density
    # correction to retain accuracy for moderately large |t|.
    if df >= 1e10:
        if t_abs > 38.5:
            # Both the normal tail and its first correction are below the
            # representable double range at this point.
            return 0.0
        normal_tail = math.erfc(t_abs / math.sqrt(2.0))
        phi = math.exp(-0.5 * t_abs * t_abs) / math.sqrt(2.0 * math.pi)
        correction = phi * (t_abs * t_abs * t_abs + t_abs) / (2.0 * df)
        return float(min(1.0, max(0.0, normal_tail + correction)))

    root_df = math.sqrt(df)
    # Compute x=df/(df+t^2) without forming t^2, which can overflow.  The
    # inverse-ratio form still underflows for enormous |t|; in that case the
    # exact survival probability can remain representable (e.g. Cauchy t=1e200).
    log_x = math.log(df) - 2.0 * math.log(t_abs)
    a, b = df / 2.0, 0.5
    if log_x < math.log(1e-300):
        # For x << 1, I_x(a,b) = x^a/(a B(a,b)) * (1 + O(x)).
        # At x<1e-300 the omitted relative correction is below floating-point
        # precision for ordinary finite df, while this log form avoids x=0.
        log_p = a * log_x - math.log(a) - (math.lgamma(a) + math.lgamma(b) - math.lgamma(a + b))
        if log_p < math.log(float.fromhex("0x0.0000000000001p-1022")):
            return 0.0
        return float(min(1.0, max(0.0, math.exp(log_p))))
    # Stable logistic evaluation of x=df/(df+t^2) and y=t^2/(df+t^2).
    # Forming exp(log_x/2) can overflow for subnormal |t| even though the
    # correct p-value is simply 1 to floating-point precision. This form only
    # exponentiates a non-positive value and so avoids that spurious exception.
    if log_x >= 0.0:
        exp_neg = math.exp(-log_x) if log_x < 746.0 else 0.0
        x = 1.0 / (1.0 + exp_neg)
        y = exp_neg / (1.0 + exp_neg)
    else:
        exp_pos = math.exp(log_x)
        x = exp_pos / (1.0 + exp_pos)
        y = 1.0 / (1.0 + exp_pos)
    # The lower-x beta branch computes tiny p-values directly. Near t=0,
    # use 1-I_y instead, where p is close to one and this is well-conditioned.
    if x < (a + 1.0) / (a + b + 2.0):
        pvalue = _reg_beta(a, b, x)
    else:
        pvalue = 1.0 - _reg_beta(b, a, y)
    return float(min(1.0, max(0.0, pvalue)))

def _reg_gamma_p(a, x):
    """Regularized lower incomplete gamma P(a,x), for positive finite a and x>=0."""
    a, x = float(a), float(x)
    if not math.isfinite(a) or a <= 0.0 or math.isnan(x) or x < 0.0:
        raise ValueError("Regularized gamma requires finite a>0 and x>=0.")
    if x == 0.0:
        return 0.0
    if x == math.inf:
        return 1.0
    if x >= a + 1.0:
        return 1.0 - _reg_gamma_q(a, x)
    # Power series; log prefactor avoids direct gamma-function overflow.
    term = total = 1.0 / a
    ap = a
    for _ in range(10000):
        ap += 1.0
        term *= x / ap
        total += term
        if abs(term) <= abs(total) * 2e-15:
            break
    log_prefactor = -x + a * math.log(x) - math.lgamma(a)
    try:
        result = math.exp(log_prefactor) * total
    except OverflowError:
        result = 1.0
    return float(min(1.0, max(0.0, result)))


def _reg_gamma_q(a, x):
    """Regularized upper incomplete gamma Q(a,x), for positive finite a and x>=0."""
    a, x = float(a), float(x)
    if not math.isfinite(a) or a <= 0.0 or math.isnan(x) or x < 0.0:
        raise ValueError("Regularized gamma requires finite a>0 and x>=0.")
    if x == 0.0:
        return 1.0
    if x == math.inf:
        return 0.0
    if x < a + 1.0:
        return 1.0 - _reg_gamma_p(a, x)
    # Continued fraction for the upper tail.
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / (b if abs(b) > tiny else tiny)
    h = d
    for i in range(1, 10001):
        an = -float(i) * (float(i) - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) <= 2e-15:
            break
    log_prefactor = -x + a * math.log(x) - math.lgamma(a)
    try:
        result = math.exp(log_prefactor) * h
    except OverflowError:
        result = 0.0
    return float(min(1.0, max(0.0, result)))


def _f_pvalue(f_stat, df1, df2):
    """Right-tail p-value for an F(df1, df2) statistic via regularized beta."""
    f_stat = float(f_stat)
    df1 = float(df1)
    df2 = float(df2)
    if not math.isfinite(df1) or not math.isfinite(df2) or df1 <= 0 or df2 <= 0:
        raise ValueError("F-test degrees of freedom must be finite and positive.")
    if math.isnan(f_stat) or f_stat < 0:
        raise ValueError("F statistic must be non-negative and not NaN.")
    if f_stat == math.inf:
        return 0.0
    if f_stat == 0.0:
        return 1.0
    if f_stat == 1.0 and df1 == df2:
        # Exact reciprocal symmetry, also avoids catastrophic cancellation
        # when both degrees of freedom are extremely large.
        return 0.5
    # When both degrees of freedom are large, approximate log(F) directly.
    # This retains variance contributed by BOTH finite dfs. A first Edgeworth
    # correction accounts for the skewness of the log-F distribution. The prior
    # one-sided Wilson-Hilferty limit could err by about 0.004 near F=1 when
    # the other degree of freedom was large but not infinite.
    _one_sided_gamma_is_stable = (
        (df2 > 1.0e9 and df2 / df1 > 1.0e8 and 0.5 * df1 <= 2.0e6) or
        (df1 > 1.0e9 and df1 / df2 > 1.0e8 and 0.5 * df2 <= 2.0e6)
    )
    if (not _one_sided_gamma_is_stable and
            ((df1 >= 1.0e6 and df2 >= 1.0e6) or
             (df1 >= 1.0e4 and df2 >= 1.0e4 and max(df1, df2) > 1.0e9))):
        def _log_gamma_centered(d):
            # psi(d/2)-log(d/2), asymptotic expansion through O(d^-4).
            inv = 1.0 / d
            return -inv - inv * inv / 3.0 + 2.0 * inv**4 / 15.0
        def _log_gamma_variance(d):
            # trigamma(d/2), asymptotic expansion through O(d^-5).
            inv = 1.0 / d
            return 2.0*inv + 2.0*inv**2 + 4.0*inv**3/3.0 - 16.0*inv**5/15.0
        def _log_gamma_kappa3(d):
            # tetragamma(d/2), asymptotic expansion through O(d^-6).
            inv = 1.0 / d
            return -4.0*inv**2 - 8.0*inv**3 - 8.0*inv**4 + 32.0*inv**6/3.0
        mean_log_f = _log_gamma_centered(df1) - _log_gamma_centered(df2)
        variance_log_f = _log_gamma_variance(df1) + _log_gamma_variance(df2)
        sd_log_f = math.sqrt(variance_log_f)
        z = (math.log(f_stat) - mean_log_f) / sd_log_f
        if z >= 38.5:
            return 0.0
        if z <= -38.5:
            return 1.0
        # For moderately large dfs, the incomplete-beta evaluation is more
        # accurate in far tails than a first-order Edgeworth expansion. Keep
        # the asymptotic path for central probabilities; use beta below for
        # |z|>6 when the parameters are still within the tested beta range.
        if abs(z) > 6.0 and max(df1, df2) <= 1.0e9:
            pass  # fall through to the direct incomplete-beta calculation
        else:
            # For dfs near the largest finite floats, sd**3 can underflow even
            # though the true standardized skewness is simply negligible. Avoid a
            # zero-division; at this scale the omitted skew correction is far below
            # double-precision resolution.
            if sd_log_f < 1.0e-90:
                skew_log_f = 0.0
            else:
                skew_log_f = (_log_gamma_kappa3(df1) - _log_gamma_kappa3(df2)) / (sd_log_f**3)
            normal_pdf = math.exp(-0.5*z*z) / math.sqrt(2.0*math.pi) if abs(z) < 38.5 else 0.0
            # Evaluate the survival tail directly instead of 1-CDF; subtraction
            # would round representable tails (e.g. ~2e-17) down to zero.
            tail = 0.5 * math.erfc(z / math.sqrt(2.0)) - (skew_log_f / 6.0) * (1.0 - z*z) * normal_pdf
            return float(min(1.0, max(0.0, tail)))
    # As df -> infinity, F(df1,df2) tends to chi-square/df1 when denominator
    # df is huge, and to df2/chi-square when numerator df is huge. Use the
    # gamma routines while their shape parameter remains in a numerically tested
    # range; for larger shape parameters use Wilson-Hilferty's cube-root normal
    # approximation rather than the internal gamma series (which loses accuracy
    # for shapes in the multi-million range).
    _GAMMA_SHAPE_MAX = 2.0e6
    if df1 < 1e8 and df2 > 1e9:
        shape = 0.5 * df1
        if shape <= _GAMMA_SHAPE_MAX:
            x_chi = shape * f_stat
            return _reg_gamma_q(shape, x_chi) if math.isfinite(x_chi) else 0.0
        # F ~ chi-square(df1)/df1. Wilson-Hilferty transform of X/df1.
        root_ratio = math.exp(math.log(f_stat) / 3.0)
        z = (root_ratio - (1.0 - 1.0 / (9.0 * shape))) / math.sqrt(1.0 / (9.0 * shape))
        tail = 0.5 * math.erfc(z / math.sqrt(2.0))
        return float(min(1.0, max(0.0, tail)))
    if df1 > 1e9 and df2 < 1e8:
        shape = 0.5 * df2
        if shape <= _GAMMA_SHAPE_MAX:
            x_chi = shape / f_stat
            return _reg_gamma_p(shape, x_chi) if math.isfinite(x_chi) else 1.0
        # F ~ df2/chi-square(df2), so the survival probability is the lower
        # chi-square tail at df2/f_stat; transform that lower-tail argument.
        root_ratio = math.exp(-math.log(f_stat) / 3.0)
        z = (root_ratio - (1.0 - 1.0 / (9.0 * shape))) / math.sqrt(1.0 / (9.0 * shape))
        tail = 0.5 * math.erfc(-z / math.sqrt(2.0))
        return float(min(1.0, max(0.0, tail)))
    if df1 >= 1e8 and df2 >= 1e8 and max(df1, df2) > 1e9:
        # Delta-method normal approximation for log(F). The first-order mean
        # correction is important when the two dfs differ; variance is the
        # sum of the log-chi-square variances to leading order.
        log_f = math.log(f_stat)
        mean_log_f = -1.0 / df1 + 1.0 / df2
        sd_log_f = math.sqrt(2.0 / df1 + 2.0 / df2)
        z = (log_f - mean_log_f) / sd_log_f
        tail = 0.5 * math.erfc(z / math.sqrt(2.0))
        return float(min(1.0, max(0.0, tail)))
    # Stable equivalent of df2/(df2 + df1*F): avoid overflow in df1*F
    # when F is extremely large, while retaining accuracy near F=0.
    ratio = df1 / df2
    if f_stat > 1.0 and ratio > 0.0 and math.isfinite(ratio):
        inv = (1.0 / f_stat) / ratio
        x = inv / (1.0 + inv)
        y_comp = 1.0 / (1.0 + inv)
    else:
        product = ratio * f_stat
        if math.isfinite(product):
            x = 1.0 / (1.0 + product)
            y_comp = product / (1.0 + product)
        else:
            x, y_comp = 0.0, 1.0
    # Use the complement only where the beta routine itself would switch to
    # its upper-tail branch; otherwise the direct I_x evaluation is more stable
    # (important for extremely small survival probabilities such as F=100).
    a, b = df2 / 2.0, df1 / 2.0
    if x >= (a + 1.0) / (a + b + 2.0):
        pvalue = 1.0 - _reg_beta(b, a, y_comp)
    else:
        pvalue = _reg_beta(a, b, x)
    return float(min(1.0, max(0.0, pvalue)))


def _student_t_crit(df, alpha=0.05):
    """Two-sided Student-t critical value by directly inverting its survival probability."""
    df = float(df)
    alpha = float(alpha)
    if not math.isfinite(df) or df <= 0:
        raise ValueError("Student-t degrees of freedom must be finite and positive.")
    if not math.isfinite(alpha) or not 0.0 < alpha < 1.0:
        raise ValueError("Two-sided significance level alpha must lie strictly between 0 and 1.")

    lo, hi = 0.0, 1.0
    # Invert the two-sided p-value rather than CDF=1-alpha/2. The CDF can round
    # to exactly 1 in the upper tail, which previously stopped the search too soon.
    while _student_t_pvalue(hi, df) > alpha:
        if hi > sys.float_info.max / 2.0:
            raise OverflowError("Requested t critical value exceeds the finite floating-point range.")
        hi *= 2.0
    for _ in range(160):
        mid = lo + (hi - lo) / 2.0
        if mid == lo or mid == hi:
            break
        if _student_t_pvalue(mid, df) > alpha:
            lo = mid
        else:
            hi = mid
    return float(lo + (hi - lo) / 2.0)

def _market_quantities(a: float, b: float, c: float, d: float, price: float) -> tuple[float, float]:
    """Quantity demanded/supplied at a non-negative price, with zero-quantity corners."""
    vals=(float(a),float(b),float(c),float(d),float(price))
    if not all(math.isfinite(z) for z in vals):
        raise ValueError("Market parameters a,b,c,d,price must all be finite.")
    if vals[1] <= 0 or vals[3] <= 0:
        raise ValueError("Market demand slope b and supply slope d must both be > 0.")
    p=max(0.0,vals[4])
    return max(0.0, vals[0] - vals[1]*p), max(0.0, vals[2] + vals[3]*p)


def _integrate_supply_quantity(a, b, c, d, p_low, p_high):
    """Exact integral of clipped supply Qs(P)=max(0,c+dP) over [p_low,p_high]."""
    d=float(d); c=float(c)
    lo=max(0.0,float(p_low)); hi=max(lo,float(p_high))
    p_start=max(lo,-c/d,0.0)
    if hi<=p_start:
        return 0.0
    return max(0.0,c*(hi-p_start)+0.5*d*(hi*hi-p_start*p_start))


def _autarky_price(a, b, c, d):
    """Price that eliminates imports for clipped linear demand/supply.

    Uses the positive-quantity interior crossing when it exists. If supply and
    demand do not cross at a positive quantity, the demand choke price is the
    convention used to represent the no-trade/autarky corner.
    """
    a, b, c, d = map(float, (a, b, c, d))
    if b <= 0 or d <= 0:
        raise ValueError("Demand and supply slopes must be positive.")
    p_int = (a - c) / (b + d)
    q_int = a - b * p_int
    if p_int >= 0 and q_int > 1e-10 and c + d * p_int >= -1e-10:
        return float(p_int)
    return float(max(0.0, a / b))


def _imports_at_price(a, b, c, d, price):
    qd, qs = _market_quantities(a, b, c, d, price)
    return max(0.0, qd - qs)


def _quota_price(a, b, c, d, world_price, quota, upper_price=None):
    """Solve imports(P)=quota by bisection for clipped linear schedules."""
    pw = max(0.0, float(world_price)); quota = max(0.0, float(quota))
    if _imports_at_price(a, b, c, d, pw) <= quota:
        return pw
    if upper_price is not None:
        explicit_hi=float(upper_price)
        if not math.isfinite(explicit_hi):
            raise ValueError("upper_price must be finite when supplied.")
        if explicit_hi < pw:
            raise ValueError("upper_price must be at least the world price.")
        hi=explicit_hi
    else:
        hi=max(pw,_autarky_price(a,b,c,d))
    # At the autarky/no-import cutoff, imports must be zero; keep that economically
    # meaningful upper bound rather than extending the price search unnecessarily.
    lo = pw
    if hi <= lo + 1e-12:
        return float(hi)
    for _ in range(100):
        mid = 0.5 * (lo + hi)
        if _imports_at_price(a,b,c,d,mid) > quota:
            lo = mid
        else:
            hi = mid
    return float(0.5 * (lo + hi))


def solve_market(a: float, b: float, c: float, d: float, t: float = 0.0) -> tuple[float, float, float, float, float]:
    """Competitive market with non-negative prices/quantities and per-unit tax.

    Demand is Qd=max(0,a-bP); supply is Qs=max(0,c+dP). For an interior
    equilibrium the usual linear formulas apply. At a non-trading corner the
    reported price is a convenient reservation/choke-price representation;
    it is not a unique market-clearing price if both schedules leave a gap.
    """
    a,b,c,d,t = map(float, (a,b,c,d,t))
    if not all(math.isfinite(z) for z in (a, b, c, d, t)):
        raise ValueError("Market intercepts, slopes, and tax must all be finite numbers.")
    if b <= 0 or d <= 0:
        raise ValueError("Demand and supply slopes must be positive.")
    if t < 0:
        raise ValueError("Per-unit tax must be >= 0; model subsidies with the dedicated subsidy model.")
    p_int=(a-c)/(b+d)
    q_int=a-b*p_int
    if p_int < 0:
        # The interior crossing lies below the admissible price domain. At P=0
        # there is either excess supply (qd0 < qs0) or no demand. There is no
        # positive-price competitive equilibrium; report the zero-price boundary
        # with the demand-limited quantity rather than inventing a negative price.
        p0=0.0
        qd0,qs0=_market_quantities(a,b,c,d,0.0)
        q0=qd0 if qd0 > 0 else 0.0
    elif q_int <= 0 or c+d*p_int < 0:
        p0=max(0.0,a/b)
        q0=0.0
    else:
        p0=p_int; q0=max(0.0,q_int)
    # Tax-inclusive buyer price Pc and seller receipt Ps, if an interior traded solution exists.
    ps_int=(a-c-b*t)/(b+d)
    pc_int=ps_int+t
    qd,qs=_market_quantities(a,b,c,d,pc_int)
    qs_at_ps=max(0.0,c+d*max(0.0,ps_int))
    if ps_int >= 0 and pc_int >= 0 and qd > 0 and abs(qd-qs_at_ps) <= 1e-7*max(1.0,qd,qs_at_ps):
        return float(p0),float(q0),float(ps_int),float(pc_int),float(qd)
    # A sufficiently large tax eliminates trade. The displayed no-trade prices
    # are reservation bounds, not a unique equilibrium price. The UI labels this as a no-trade boundary.
    return float(p0),float(q0),0.0,float(max(0.0,a/b)),0.0


def market_surplus(v):
    """Return CS and PS using the same non-negative-price supply curve as the graph."""
    a, b, c, d = v["demand"], v["dslope"], v["supply"], v["sslope"]
    p0, q0, _, _, _ = solve_market(a, b, c, d, 0.0)
    q0 = max(0.0, q0)
    if q0 <= 0:
        return 0.0, 0.0
    demand_choke = a / b
    cs = 0.5 * q0 * max(0.0, demand_choke - p0)
    # Supply is constrained to P>=0 in the graph: P_s(Q)=max(0,(Q-c)/d).
    q_flat = min(q0, max(0.0, c))
    q_rising = max(0.0, q0 - q_flat)
    ps = p0 * q_flat
    if q_rising > 0:
        if c >= 0:
            ps += q_rising * p0 - 0.5 * q_rising * q_rising / d
        else:
            # With c<0, inverse supply is already positive at Q=0.
            ps += q_rising * p0 - (0.5*q_rising*q_rising - c*q_rising) / d
    return float(max(0.0, cs)), float(max(0.0, ps))

def ext_values(v, topic):
    """Solve externality quantities on the same non-negative-price curves as the graph.

    Private benefit is MPB(Q)=max(0,(a-Q)/b), private cost is MPC(Q)=max(0,(Q-c)/d).
    Negative externality: MSC=MPC+e+s*Q/10. Vaccination: MSB=MPB+bn.
    The monotone equations are solved by bisection so the c>0 flat supply segment
    and non-negative benefit/cost corners are handled without extrapolating curves.
    """
    a, b, c, d = map(float, (v["demand"], v["dslope"], v["supply"], v["sslope"]))
    e, s, bn = (max(0.0, float(v.get("external", 0))),
                max(0.0, float(v.get("msc_slope", 0))),
                max(0.0, float(v.get("benefit", 0))))
    mpb = lambda q: max(0.0, (a - q) / b)
    mpc = lambda q: max(0.0, (q - c) / d)
    _, Qm, _, _, _ = solve_market(a, b, c, d, 0.0)
    Qm = max(0.0, float(Qm))
    if topic == "Vaccination Externality":
        f = lambda q: mpb(q) + bn - mpc(q)
        lo = 0.0
        hi = max(1.0, a, c, 0.0) + d * (bn + 1.0) + 1.0
        if f(lo) <= 0:
            Qs = 0.0
        else:
            for _ in range(120):
                mid = (lo + hi) / 2.0
                if f(mid) > 0: lo = mid
                else: hi = mid
            Qs = (lo + hi) / 2.0
        ts = bn
    else:
        f = lambda q: mpb(q) - (mpc(q) + e + s * q / 10.0)
        if f(0.0) <= 0:
            Qs = 0.0
        else:
            lo, hi = 0.0, max(0.0, a)
            if f(hi) > 0:
                Qs = hi
            else:
                for _ in range(120):
                    mid = (lo + hi) / 2.0
                    if f(mid) > 0: lo = mid
                    else: hi = mid
                Qs = (lo + hi) / 2.0
        ts = e + s * Qs / 10.0
    return a, b, c, d, e, s, bn, float(Qm), float(Qs), float(ts)

def public_good(v):
    """Return the efficient public-good quantity with nonnegative individual MBs."""
    m1, m2, mc, dc = map(float, (v["mb1"], v["mb2"], v["mcpub"], v["decay"]))
    if mc >= (m1 + m2):
        return 0.0
    q_both = (m1 + m2 - mc) / (2 * dc)
    if q_both >= 0 and q_both <= min(m1, m2) / dc + 1e-12:
        return float(q_both)
    hi, lo = max(m1, m2), min(m1, m2)
    q_one = (hi - mc) / dc
    if q_one >= lo / dc - 1e-12 and q_one <= hi / dc + 1e-12:
        return float(max(0.0, q_one))
    return 0.0

def _irr(cfs: list[float] | np.ndarray) -> list[float]:
    """Find admissible real IRRs robustly, including multiple sign-change cases.

    The substitution x=1/(1+r) converts NPV(r)=0 into a polynomial in x on
    the economically admissible domain x>0. Polynomial roots are used first;
    a logarithmic positive-x scan then brackets additional real roots that can
    be missed by ill-conditioned high-degree companion-matrix calculations.
    """
    cf = np.asarray(list(cfs), dtype=float).reshape(-1)
    if cf.size == 0 or not np.all(np.isfinite(cf)):
        return []
    scale = max(1.0, float(np.sum(np.abs(cf))))
    tol = 1e-9 * scale
    # Polynomial in descending powers of x: CF_N*x^N + ... + CF_1*x + CF_0.
    coeff = cf[::-1].copy()
    while coeff.size > 1 and abs(coeff[0]) <= 1e-14 * scale:
        coeff = coeff[1:]
    if coeff.size <= 1:
        return []

    def npv_x(x: float) -> float:
        # Horner evaluation is more stable than repeatedly forming (1+r)^(-t).
        total = 0.0
        for c in cf[::-1]:
            total = total * x + c
        return float(total)

    candidates: list[float] = []
    try:
        roots_x = np.roots(coeff)
    except (ValueError, np.linalg.LinAlgError):
        roots_x = np.array([], dtype=complex)
    for z in roots_x:
        if abs(z.imag) <= 1e-7 * max(1.0, abs(z.real)) and z.real > 0:
            x = float(z.real)
            val = npv_x(x)
            if math.isfinite(val) and abs(val) <= 1e-7 * scale * max(1.0, x ** max(0, cf.size-1)):
                candidates.append(1.0 / x - 1.0)

    # Bracket roots over x>0 in log-space. This is a fallback for high-degree
    # or poorly conditioned polynomials where np.roots may lose a real root.
    grid = np.logspace(-12, 12, 2400)
    prev_x = float(grid[0]); prev_f = npv_x(prev_x)
    for x in grid[1:]:
        x = float(x); fx = npv_x(x)
        if not (math.isfinite(prev_f) and math.isfinite(fx)):
            prev_x, prev_f = x, fx
            continue
        # Do not treat a merely small sampled NPV as a root. In particular,
        # when CF_0 == 0 the polynomial tends to zero as x -> 0, so an absolute
        # tolerance here incorrectly labels many grid points as distinct, huge
        # IRRs. Simple roots are bracketed by sign changes; repeated roots are
        # obtained from the polynomial-root pass above.
        if (prev_f < 0.0 < fx) or (fx < 0.0 < prev_f):
            lo, hi = prev_x, x
            flo, fhi = prev_f, fx
            for _ in range(120):
                mid = 0.5 * (lo + hi)
                if mid == lo or mid == hi:
                    break
                fm = npv_x(mid)
                if flo * fm <= 0.0:
                    hi, fhi = mid, fm
                else:
                    lo, flo = mid, fm
                if hi - lo <= 1e-13 * max(1.0, abs(mid)):
                    break
            candidates.append(1.0 / (0.5 * (lo + hi)) - 1.0)
        prev_x, prev_f = x, fx

    candidates.sort()
    out: list[float] = []
    for r in candidates:
        if not math.isfinite(r) or r <= -1.0:
            continue
        x = 1.0 / (1.0 + r)
        residual = abs(npv_x(x))
        if residual > 1e-6 * scale * max(1.0, x ** max(0, cf.size-1)):
            continue
        if not out or abs(r - out[-1]) > 1e-7 * max(1.0, abs(r), abs(out[-1])):
            out.append(float(r))
        else:
            # Polynomial roots are often more accurate than nearby scan roots.
            # Keep whichever candidate has the smaller NPV residual instead of
            # automatically retaining the numerically smaller rate.
            prev = out[-1]
            prev_x = 1.0 / (1.0 + prev)
            curr_x = 1.0 / (1.0 + r)
            if abs(npv_x(curr_x)) < abs(npv_x(prev_x)):
                out[-1] = float(r)
    return out

def _regdata(v, hetero=False):
    n = int(v["nobs"]); rng = np.random.default_rng(42)
    z = rng.standard_normal(n); e = rng.standard_normal(n)
    x = v["xmean"] + v["xsd"] * z
    sd = v["se"] * (np.maximum(.1, 1 + (x - v["xmean"]) / v["xsd"]) if hetero else 1)
    y = v["intercept"] + v["slope"] * x + sd * e
    return x, y

def _ols(x, y):
    b1, b0 = np.polyfit(x, y, 1)
    res = y - (b0 + b1 * x)
    sst = float(((y - y.mean()) ** 2).sum())
    r2 = 1 - float((res ** 2).sum()) / sst if sst > 0 else 0.0
    return b0, b1, r2, res

def _bayesian_symmetric_pure_bne(R, T, S, P, pH, tol=1e-12):
    """Enumerate pure symmetric BNE in a two-type symmetric Bayesian 2x2 game.

    Assumptions: both players have independently drawn H/L types with common prior
    P(H)=pH; each type chooses A/B; both types share the same payoff matrix
    u(A,A)=R, u(A,B)=S, u(B,A)=T, u(B,B)=P. Because payoffs do not vary by own
    type, type-contingent actions can differ only when the player is indifferent.
    Returns strategy tuples (action_H, action_L), where 0=A and 1=B.
    """
    pH = float(pH)
    if not 0.0 <= pH <= 1.0:
        raise ValueError("P(Type H) must lie in [0, 1].")
    # own action, opponent action -> own payoff
    payoff = ((float(R), float(S)), (float(T), float(P)))
    strategies = ((0, 0), (0, 1), (1, 0), (1, 1))
    equilibria = []
    for strategy in strategies:
        expected = [pH * payoff[a][strategy[0]] + (1.0-pH) * payoff[a][strategy[1]] for a in (0, 1)]
        valid = True
        for own_type_action in strategy:
            if expected[own_type_action] + tol < expected[1-own_type_action]:
                valid = False
                break
        if valid:
            equilibria.append(strategy)
    return equilibria


def _game_matrices(v):
    """Return row/column payoffs using rows=Player 1 actions, columns=Player 2 actions.

    R=(A,A), S=(A,B), T=(B,A), P=(B,B) for Player 1; for Player 2,
    its own action is the column, so its off-diagonal T/S cells are reversed.
    """
    row = [[v["pR"], v["pS"]], [v["pT"], v["pP"]]]
    col = [[v.get("qR", v["pR"]), v.get("qT", v["pT"])],
           [v.get("qS", v["pS"]), v.get("qP", v["pP"])]]
    return row, col

def _game(v):
    row, col = _game_matrices(v)
    nash = [(i, j) for i in range(2) for j in range(2)
            if row[i][j] >= row[1-i][j] and col[i][j] >= col[i][1-j]]
    return row, nash

def _game_mixed(v):
    R,T,S,P = v["pR"],v["pT"],v["pS"],v["pP"]
    R2,T2,S2,P2 = v.get("qR",R),v.get("qT",T),v.get("qS",S),v.get("qP",P)
    denom1 = R-T-S+P
    denom2 = R2-T2-S2+P2
    if abs(denom1)<1e-12 or abs(denom2)<1e-12: return None
    # Row-player indifference determines the column player's probability q(A).
    p2_A=(P-S)/denom1
    # Column-player indifference determines the row player's probability p(A).
    p1_A=(P2-S2)/denom2
    if 0<p1_A<1 and 0<p2_A<1: return p1_A,p2_A
    return None


# v44 mathematical solution cards for the newly added teaching models.
MATH_SOLUTIONS.update({
"Intertemporal Choice / Fisher Separation Theorem":
"""MODEL: U = ln(c1) + β ln(c2), with β = 1/(1+ρ).
INTERTEMPORAL BUDGET: c1 + c2/(1+r) = W.
Fisher separation: saving/borrowing transfers resources across dates; the optimal
consumption path satisfies MU(c1) = (1+r)·β·MU(c2), so c2/c1 = β(1+r).
""",
"Behavioral Economics / Prospect Theory":
"""VALUE FUNCTION: v(x)=x^α for gains and v(x)=-λ(-x)^α for losses.
The reference point is the origin for gains/losses after framing.
Loss aversion is represented by λ>1; a loss of a given magnitude therefore
has greater decision weight than an equal-sized gain.
""",
"General Equilibrium & Edgeworth Box":
"""ENDOWMENT: Consumer A starts at (ωₓ,ωᵧ) inside a box with total resources
(X̄,Ȳ); Consumer B receives the residual (X̄−ωₓ,Ȳ−ωᵧ).
CONTRACT CURVE: with identical Cobb–Douglas preferences, MRS_A=MRS_B implies
y_A/x_A=Ȳ/X̄, the diagonal through the two box origins; it is independent of
prices. The competitive budget line passes through A's endowment with slope
−pₓ/pᵧ. Pareto efficiency means no feasible Pareto-improving reallocation.
""",
"Risk and Uncertainty":
"""EXPECTED UTILITY: EU = Σ p_s u(x_s).
For CRRA utility u(c)=c^(1−γ)/(1−γ), γ>0.
RISK AVERSION: A(c)=−u''(c)/u'(c)>0. A fair gamble can have a certainty
equivalent below its expected monetary value.
""",
"DSGE Core Blocks":
"""CORE BLOCKS: Euler equation, capital accumulation, and an exogenous shock.
A representative household satisfies u'(c_t)=β(1+r_{t+1}−δ)u'(c_{t+1}).
Capital evolves k_{t+1}=(1−δ)k_t+i_t. The plotted path is a teaching
linearized/RBC-style response, not a calibrated DSGE estimation.
""",
"Mundell-Fleming Model":
"""IS-LM-BP LOGIC: under high capital mobility, monetary/fiscal policy effects
depend on the exchange-rate regime. Floating exchange rates allow the exchange
rate to adjust; fixed rates require central-bank intervention to defend parity.
The BP schedule is horizontal in the limiting perfect-capital-mobility case.
""",
"Ricardian Equivalence":
"""LIFETIME BUDGET: PV(c) = PV(income) − PV(taxes).
With lump-sum taxes, perfect capital markets, forward-looking households, and
no borrowing constraints, a debt-financed tax cut raises future taxes by its
present value and does not change lifetime resources or desired consumption.
""",
"Difference-in-Differences (DiD)":
"""2×2 ESTIMAND: DiD = (Y_T,post−Y_T,pre) − (Y_C,post−Y_C,pre).
IDENTIFICATION: the treatment and control groups must have parallel trends in
the absence of treatment. The graph shows pre/post paths and the estimated jump.
""",
"Regression Discontinuity Design (RDD)":
"""CUTOFF RULE: treatment D=1[X≥c].
LOCAL EFFECT: τ_RDD = lim_{x↓c}E[Y|X=x] − lim_{x↑c}E[Y|X=x].
Identification requires continuity of untreated potential outcomes at the cutoff.
""",
"Vector Autoregression (VAR) & Impulse Response Functions (IRF)":
"""VAR(1): y_t = A y_{t−1}+ε_t.
An impulse response traces E[y_{t+h}|ε_t=e]−E[y_{t+h}|ε_t=0].
With persistence |ρ|<1, a one-unit shock decays geometrically in the teaching IRF.
""",
"Stolper-Samuelson & Rybczynski Theorems":
"""STOLPER-SAMUELSON: with standard Heckscher-Ohlin assumptions, a rise in the
relative price of a good raises the real return to its intensively used factor.
RYBCZYNSKI: holding goods prices fixed, an increase in one factor endowment
raises output of the good using that factor intensively and reduces the other.
""",
"Optimum Currency Area (OCA) Criteria":
"""OCA LOGIC: the costs of giving up an independent exchange rate fall when
labor/capital mobility is high, fiscal transfers are available, and business
cycles are synchronized. The plotted OCA index is a transparent composite,
not a canonical empirical estimator.
""",
"Dual-Economy Migration (Todaro Model)":
"""EXPECTED URBAN INCOME: E(W_u)=(1−u)W_u.
MIGRATION occurs when E(W_u) exceeds the rural wage W_r, subject to migration
costs. Equilibrium can feature positive urban unemployment because migrants
respond to expected rather than guaranteed urban earnings.
""",
"Health-Led Growth & Demographic Dividend":
"""DEPENDENCY RATIO = dependents / working-age population.
A demographic dividend is feasible when the working-age share rises while
dependency falls, provided employment, health, and human-capital conditions
allow the larger working-age population to be productively absorbed.
""",
"Tiebout Hypothesis":
"""ILLUSTRATIVE INDEX CURVES: Preference(x)=G·x^(1/sorting), Tax(x)=income·(1−x),
for normalized x∈[0,1] and positive sorting intensity. The plotted intersection
compares these two indices; it is a conceptual schematic, not a structural
Tiebout equilibrium or an empirically estimated household/jurisdiction choice model.
""",
"Mechanism Design / Vickrey Auctions":
"""SECOND-PRICE SEALED-BID AUCTION: truthful bidding is a weakly dominant strategy
for a private-value bidder. The winner pays the highest losing bid, so surplus
equals value minus the second-highest bid.
""",
"Human Capital Earnings Function (Mincer)":
"""MINCER EQUATION: ln(w)=ln(w_base)+β_s·schooling+β_1·experience+β_2·experience²,
where α=ln(w_base). The quadratic experience term permits concave earnings
profiles; β_s is the semi-elastic return to an additional year of schooling.
""",
"Collective Bargaining / Bilateral Monopoly":
"""BILATERAL MONOPOLY: a union supplies labor collectively while the employer has
wage-setting power. The bargaining outcome depends on relative bargaining
power and the parties' outside options; there need not be a unique competitive
wage-employment pair.
""",
"Black-Litterman Asset Allocation":
"""POSTERIOR RETURN = equilibrium prior combined with investor views, weighted by
their confidence and the uncertainty of the prior. Higher view confidence pulls
the allocation toward the view; low confidence leaves it closer to equilibrium.
This implementation is a transparent two-asset teaching approximation.
""",
"Real Options Valuation":
"""CRR BINOMIAL OPTION: this implementation values a European-style call on project
value with terminal payoff max(S_T−K, 0), using a fixed number of CRR steps and
backward induction. It is a teaching proxy, not a full American-style real option
with early exercise, expansion, or abandonment decisions. The no-arbitrage condition
d < exp(r·Δt) < u must hold; invalid parameter combinations are rejected.
""",
"Integrated Assessment Model (IAM) Damage Function":
"""DAMAGE FUNCTION: D(T)=1−exp(−φT²) or, for small damage, D(T)≈φT².
Net output = Y·(1−D(T)). The curve is a stylized IAM damage block, not a calibrated
climate-economy model.
""",
"Fishery / Forestry Optimal Rotation (Gordon-Schaefer)":
"""LOGISTIC STOCK GROWTH: G(X)=rX(1−X/K), with r and harvest H measured per time unit.
HARVEST H=qEX. MSY occurs at X=K/2 with H_MSY=rK/4.
Open access tends toward zero rent where total revenue equals total cost;
the Gordon-Schaefer teaching graph contrasts MSY with that bioeconomic boundary.
""",
"Optimal Control Theory / HJB Foundations":
"""HJB: ρV(x)=max_u{π(x,u)+V_x(x)f(x,u)} in continuous time.
The costate/shadow value summarizes the marginal value of the state. Optimal
paths satisfy the state equation plus the costate equation and a transversality
condition.
""",
"Phase Plane Analysis":
"""PHASE PLANE: \u1e8b=f(k,c), ċ=g(k,c).
Nullclines satisfy f=0 and g=0. Their intersection is a steady state; the
Jacobian eigenvalues determine local stability. A saddle path is the stable
manifold when one eigenvalue is positive and one negative.
""",
"Signalling Games / Job Market Signalling":
"""SEPARATING EQUILIBRIUM: high-productivity workers choose a signal when its cost
is sufficiently low for them but sufficiently high for low-productivity workers.
POOLING EQUILIBRIUM: both types choose the same signal. Beliefs and off-path
beliefs determine incentive compatibility. The plotted reduced-form likelihoods use
exp(−signal_cost·distance/scale), with a positive scale making the exponent dimensionless;
this is not a full incentive-compatibility equilibrium.
""",
"Auction Theory":
"""FIRST-PRICE: the highest bidder wins and pays their own bid, creating a bid
shading incentive. SECOND-PRICE: the winner pays the second-highest bid.
Under standard independent-private-value assumptions, revenue equivalence
holds across standard auction formats when its conditions apply.
""",
"CBDC & Banking Disintermediation":
"""A larger CBDC deposit share can reduce commercial-bank deposits available for
loan funding. A stylized funding-cost/spread relationship is used here to show
how deposit migration can widen lending spreads absent offsetting wholesale or
central-bank funding.
""",
"Financial Accelerator Mechanism":
"""FINANCIAL ACCELERATOR: lower borrower net worth raises external-finance premia,
which reduces investment and output; weaker output can further reduce net worth.
The feedback creates amplification beyond the original shock.
""",
"Ramsey-Cass-Koopmans (RCK) Model":
"""SIMPLIFIED STATE EQUATION USED BY THIS GRAPH: ḱ=f(k)−δk−c, with f(k)=Ak^α.
EULER EQUATION USED BY THIS GRAPH: ċ/c=(1/θ)[f'(k)−δ−ρ]. Population growth n
and technology growth g are omitted from this topic's parameters and equations;
therefore this is the no-n/no-g special case, not the full general RCK system.
The phase diagram identifies the local dynamics around the steady-state nullclines;
it does not calculate a complete saddle path.
""",
"Schumpeterian Creative Destruction":
"""QUALITY-LADDER LOGIC: each successful innovation raises quality by factor (1+η).
With innovation arrival intensity ι, the continuous-time log-growth contribution
is ι·ln(1+η), plus the separately entered base growth rate. Creative destruction
replaces incumbent rents with new-innovation rents; this is a teaching-model path.
""",
"Cobweb Model":
"""DISCRETE SUPPLY AND PARTIAL PRICE ADJUSTMENT:
Demand: Qd_t = a − bP_t; supply: Qs_t = c + dP_{t−1}.
The current market-clearing price implied by lagged supply is
P_t^clear = (a − c − dP_{t−1})/b.
With adjustment speed λ, the implemented update is
P_t = max(0, (1−λ)P_{t−1} + λP_t^clear).
In the unconstrained linear case, local feedback is 1−λ−λd/b;
stability requires its absolute value to be below one. The non-negative
price floor can change paths near the boundary.
""",
"Crop Insurance & Basis Risk":
"""INDEMNITY: payout=max(0, trigger−index)×income×(1+risk/100), where risk is entered as a percentage.
BASIS RISK is the mismatch between the insured index and the farmer's realized
loss, so an actual crop loss can occur with a small payout and vice versa.
""",
"Cost-Utility Analysis (CUA)":
"""ICER = ΔCost/ΔQALY when ΔQALY ≠ 0.
For a willingness-to-pay threshold λ, incremental net monetary benefit is
INMB = λ·ΔQALY − ΔCost; the intervention is cost-effective at that threshold
when INMB ≥ 0. If ΔQALY = 0, ICER is undefined and INMB still gives the decision.
The cost-effectiveness plane has ΔQALY on the horizontal axis and ΔCost on the
vertical axis; dominant and dominated quadrants should be interpreted directly.
""",
"Managed Care Capitation":
"""CAPITATION pays a fixed amount per enrollee, shifting utilization risk to the
provider; fee-for-service pays per service and can strengthen quantity incentives.
The comparison is a teaching stylization, not a welfare ranking by itself.
""",
})

