def _assert_clean_source_text(text):
    """Raise when source-level formula text contains a known mojibake marker."""
    if any(marker in str(text) for marker in _MOJIBAKE_MARKERS):
        raise RuntimeError("EcoGraph Lab source appears to contain UTF-8-as-Latin-1 mojibake; restore a clean UTF-8 source file.")

