        _lo=min(_anchors); _hi=max(_anchors); _span=max(_hi-_lo,0.25*max(abs(_hi),abs(_lo),20.0),10.0)
        x_lo=max(0.0,_lo-0.18*_span); x_hi=max(x_lo+10.0,_hi+0.18*_span)
        x=np.linspace(x_lo,x_hi,300); imports_x=Im_E*(x/Y_ref); nx_x=X_E-imports_x
        is_i=(c0-mpc*T+I0+G+nx_x-(1-mpc)*x)/bI; lm_i=(k*x-M/P)/h
        line(x,is_i,"IS with income-dependent imports"); line(x,lm_i,"LM",2); ax.scatter([Y],[real_pct],s=45,label="Reference output/rate")
        if math.isfinite(Y_star) and math.isfinite(r_star):
            ax.scatter([Y_star],[r_star],s=95,marker="*",color=NEON_COLORS[3],zorder=10,label=f"IS–LM equilibrium (Y*={Y_star:.1f}, r*={r_star:.2f}%)")
            # Set a compact, padded rate window from the visible curves and key points.
