    if topic == "Real Options Valuation":
        vol=max(float(v.get("option_vol",.25)),.001); S0=max(float(v.get("exercise_value",120)),0.0); K=max(float(v.get("investment_cost",100)),0.0); r=float(v.get("discount",5.0))/100.0; horizon=max(float(v.get("horizon",2)),.1); n=int(np.clip(round(float(v.get("steps",2))),2,12))
        # CRR no-arbitrage requires |r| < σ√(n/H). Keep the sweep inside
