# Data-driven handler registry support. Decorated methods can advertise their topics;
# the existing advanced-topic routing remains backward compatible.
HANDLER_REGISTRY = {}
def register(*topics):
    """Register one handler function for one or more topic names."""
    def decorator(fn):
        setattr(fn, "_registered_topics", tuple(topics))
        return fn
    return decorator


def build_handler_registry(obj):
    """Build a bound-method registry in class-definition order.

    Duplicate topic ownership is a hard error so a later method cannot silently
    overwrite an earlier model handler. Definition order is used instead of
    ``dir()`` alphabetical order, making registration priority deterministic.
    """
    registry = {}
    seen_by = {}
    for cls in reversed(obj.__class__.mro()):
        for name, raw_fn in cls.__dict__.items():
            topics = getattr(raw_fn, "_registered_topics", ())
            if not topics:
                continue
            fn = getattr(obj, name, None)
            for topic in topics:
                if topic in registry:
                    old_fn = registry[topic]
                    old_name = seen_by[topic]
                    if getattr(old_fn, "__func__", old_fn) is not getattr(fn, "__func__", fn):
                        raise ValueError(f"Duplicate handler registration for topic {topic!r}: {old_name} vs {name}")
                registry[topic] = fn
                seen_by[topic] = name
    return registry

