    def export_both(self):
        filters='PNG Report (*.png);;PDF Report (*.pdf);;Word Document (*.docx);;HTML Report (*.html);;SVG Report (*.svg);;Rich Text Format (*.rtf)'
        path,selected_filter=QFileDialog.getSaveFileName(self,'Export Both','ecograph_report',filters)
        if not path:return
        path,ext=self._normalize_export_path(path,selected_filter,[('png','.png'),('pdf','.pdf'),('word','.docx'),('html','.html'),('svg','.svg'),('rich text','.rtf')])
        title=self._report_title(); solution=self._solution_text()
        try:
            self.add_watermark()
            if ext=='.png': self._export_png_report(path,title,solution)
            elif ext=='.pdf': self._export_pdf_report(path,title,solution)
            elif ext=='.docx': self._export_docx_report(path,title,solution)
            elif ext=='.html': self._export_combined_html(path,title,solution)
            elif ext=='.svg': self._export_combined_svg(path,title,solution)
            elif ext=='.rtf': self._export_combined_rtf(path,title,solution)
            QMessageBox.information(self,'Export complete',f'Graph + mathematical solution saved successfully:\n{path}')
        except Exception as e: QMessageBox.critical(self,'Export failed',f'Could not export graph + solution:\n{e}')

