        for raw in solution.splitlines(): lines.append('') if not raw else lines.extend(textwrap.wrap(raw,width=max_chars,replace_whitespace=False,drop_whitespace=False) or [''])
        if len(lines)>1000: raise ValueError(f'This solution expands to {len(lines):,} rendered lines, above the 1,000-line PNG safety limit. Choose PDF or Word for long solutions.')
        height=graph.height+28+2*lh+max(0,len(lines)-1)*lh+font_size+18; report=Image.new('RGB',(width,height),'white'); report.paste(graph,(0,0)); draw=ImageDraw.Draw(report)
