        _idx = sys.argv.index("--visual-test")
        _out = sys.argv[_idx + 1] if len(sys.argv) > _idx + 1 and not sys.argv[_idx + 1].startswith("--") else None
        _visual_ok = _run_ecograph_visual_test(_out)
        raise SystemExit(0 if _visual_ok else 1)
