    win = MainWindow()
    _base_stylesheet = app.styleSheet()
    _font_families = ["Arial", "Helvetica", "Avenir Next", "Verdana", "Tahoma", "Trebuchet MS", "Georgia", "Times New Roman", "Palatino", "Courier New", "Menlo", "Monaco", "SF Pro Display", "SF Pro Text", "DejaVu Sans"]
    def _apply_ecograph_font(family):
        # Keep all existing styles and layout; change only the selected font family.
        import matplotlib
        app.setFont(QFont(family, 12))
        app.setStyleSheet(_base_stylesheet.replace('Inter, "SF Pro Display", "Segoe UI", Arial, sans-serif', f'"{family}", "SF Pro Display", "Segoe UI", Arial, sans-serif'))
        matplotlib.rcParams['font.family'] = family
        matplotlib.rcParams['font.sans-serif'] = [family, 'Arial', 'DejaVu Sans']
        # Apply to currently rendered axes, legends, titles, annotations and figure text.
        for _ax in win.canvas.fig.axes:
            for _obj in [_ax.title, _ax.xaxis.label, _ax.yaxis.label, *_ax.get_xticklabels(), *_ax.get_yticklabels()]:
                try: _obj.set_fontfamily(family)
                except Exception: pass
            _leg = _ax.get_legend()
            if _leg is not None:
                for _txt in _leg.get_texts():
                    _txt.set_fontfamily(family)
                try: _leg.get_title().set_fontfamily(family)
                except Exception: pass
            for _txt in list(_ax.texts):
                try: _txt.set_fontfamily(family)
                except Exception: pass
        for _txt in win.canvas.fig.texts:
            try: _txt.set_fontfamily(family)
            except Exception: pass
        win.canvas.draw_idle()
    win.font_combo.currentTextChanged.connect(_apply_ecograph_font)
    _apply_ecograph_font(win.font_combo.currentText())
    win.show(); sys.exit(app.exec())
